#include <numbers>

#include <gtest/gtest.h>

#include "bench/drive.hpp"

TEST(HeadingError, TurnsTheShortWayRound) {
  constexpr bench::Goal behind{.x_m = -1.0, .y_m = 0.0};
  constexpr bench::Pose facing_away{.x_m = 0.0, .y_m = 0.0, .yaw_rad = -3.0};
  // The goal lies at pi. From -3.0 rad the short way is 0.14 rad clockwise, not 6.14 the other way.
  EXPECT_NEAR(bench::heading_error_rad(facing_away, behind), 3.0 - std::numbers::pi, 1e-12);
}

#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <format>
#include <iostream>
#include <numbers>
#include <optional>
#include <span>
#include <utility>
#include <vector>

namespace bench {

// bench/drive.hpp: the motion task, with no clock and no ROS.

// A planar pose in the odometry frame.
struct Pose {
  double x_m = 0.0;
  double y_m = 0.0;
  double yaw_rad = 0.0;
};

// Where the robot has to get to, and how close counts as arrived.
struct Goal {
  double x_m = 0.0;
  double y_m = 0.0;
  double tolerance_m = 0.10;
};

// What the follower is allowed to ask for.
struct Limits {
  double speed_mps;       // forward speed while driving
  double turn_rps;        // largest turn rate
  double turn_first_rad;  // above this heading error, turn on the spot instead of driving
  double turn_gain_hz;    // turn rate per radian of heading error while driving
};

// One command for /cmd_vel_nav.
struct Drive {
  double forward_mps = 0.0;
  double turn_rps = 0.0;
};

// The angle from -pi to pi that points the same way.
[[nodiscard]] double wrapped_rad(double angle_rad) {
  return std::remainder(angle_rad, 2 * std::numbers::pi);
}

[[nodiscard]] double range_m(const Pose& pose, const Goal& goal) {
  return std::hypot(goal.x_m - pose.x_m, goal.y_m - pose.y_m);
}

// Where the goal lies, seen from the robot's own heading.
[[nodiscard]] double heading_error_rad(const Pose& pose, const Goal& goal) {
  return wrapped_rad(std::atan2(goal.y_m - pose.y_m, goal.x_m - pose.x_m) - pose.yaw_rad);
}

[[nodiscard]] bool arrived(const Pose& pose, const Goal& goal) {
  return range_m(pose, goal) <= goal.tolerance_m;
}

[[nodiscard]] Drive drive_towards(const Pose& pose, const Goal& goal, const Limits& limits) {
  if (arrived(pose, goal)) return {};
  const double error = heading_error_rad(pose, goal);
  if (std::abs(error) > limits.turn_first_rad) {
    return {.forward_mps = 0.0, .turn_rps = std::copysign(limits.turn_rps, error)};
  }
  return {.forward_mps = limits.speed_mps,
          .turn_rps = std::clamp(limits.turn_gain_hz * error, -limits.turn_rps, limits.turn_rps)};
}

// The route from two parameter arrays. Nothing when they aren't the same length: a ROS parameter
// can't hold a list of pairs, and a mismatch would silently shorten or lengthen the route.
[[nodiscard]] std::optional<std::vector<Goal>> goals_from(std::span<const double> x_m, std::span<const double> y_m,
                                                          double tolerance_m) {
  if (x_m.size() != y_m.size() || x_m.empty()) return std::nullopt;
  std::vector<Goal> goals;
  for (std::int64_t i = 0; i < std::ssize(x_m); ++i) {
    const auto k = static_cast<std::size_t>(i);
    goals.push_back({.x_m = x_m[k], .y_m = y_m[k], .tolerance_m = tolerance_m});
  }
  return goals;
}

// Drives a list of goals in order and stops at the last one. It reads nothing but the pose.
class Route {
 public:
  Route(std::vector<Goal> goals, Limits limits) : goals_(std::move(goals)), limits_(limits) {}

  // The command for this pose. A goal counts as reached the first time the robot is inside it.
  [[nodiscard]] Drive on_pose(const Pose& pose) {
    while (!done() && arrived(pose, goals_[static_cast<std::size_t>(reached_)])) ++reached_;
    if (done()) return {};
    return drive_towards(pose, goals_[static_cast<std::size_t>(reached_)], limits_);
  }

  [[nodiscard]] std::int64_t reached() const { return reached_; }
  [[nodiscard]] bool done() const { return reached_ == std::ssize(goals_); }

 private:
  std::vector<Goal> goals_;
  Limits limits_;
  std::int64_t reached_ = 0;
};

}  // namespace bench

// A differential-drive robot with no slip, no delay and no acceleration limit. It is not the
// simulator: it is enough to show that the route's own logic converges.
struct Wheelbase {
  bench::Pose pose;

  void step(const bench::Drive& drive, double dt_s) {
    pose.x_m += drive.forward_mps * std::cos(pose.yaw_rad) * dt_s;
    pose.y_m += drive.forward_mps * std::sin(pose.yaw_rad) * dt_s;
    pose.yaw_rad = bench::wrapped_rad(pose.yaw_rad + drive.turn_rps * dt_s);
  }
};

int main() {
  constexpr double dt_s = 0.05;
  constexpr bench::Limits limits{
      .speed_mps = 0.20, .turn_rps = 0.60, .turn_first_rad = 0.20, .turn_gain_hz = 1.5};
  constexpr std::array<double, 2> x_m{0.80, 0.80};
  constexpr std::array<double, 2> y_m{0.00, 0.50};
  const std::optional<std::vector<bench::Goal>> goals = bench::goals_from(x_m, y_m, 0.10);
  if (!goals) return 1;
  bench::Route route(*goals, limits);
  Wheelbase robot;
  std::int64_t reached = 0;
  std::int64_t tick = 0;
  for (; tick <= 400 && !route.done(); ++tick) {
    const bench::Drive drive = route.on_pose(robot.pose);
    if (route.reached() != reached) {
      reached = route.reached();
      std::cout << std::format("{:5.2f} s: goal {} reached at ({:.2f}, {:.2f})\n", static_cast<double>(tick) * dt_s,
                               reached, robot.pose.x_m, robot.pose.y_m);
    }
    if (tick % 40 == 0) {
      std::cout << std::format("{:5.2f} s: at ({:5.2f}, {:5.2f}) facing {:5.2f} rad, forward {:.2f} m/s, turn {:5.2f} rad/s\n",
                               static_cast<double>(tick) * dt_s, robot.pose.x_m, robot.pose.y_m, robot.pose.yaw_rad,
                               drive.forward_mps, drive.turn_rps);
    }
    robot.step(drive, dt_s);
  }
  std::cout << std::format("finished after {:.2f} s, {} goals reached, at ({:.2f}, {:.2f})\n",
                           static_cast<double>(tick) * dt_s, route.reached(), robot.pose.x_m, robot.pose.y_m);
  constexpr std::array<double, 1> one_y{0.00};
  std::cout << std::format("two x and one y make a route: {}\n", bench::goals_from(x_m, one_y, 0.10).has_value());
}

