  [[nodiscard]] std::int64_t reached() const { return reached_; }
  [[nodiscard]] bool done() const { return reached_ == std::ssize(goals_); }

 private:
  std::vector<Goal> goals_;
  Limits limits_;
  std::int64_t reached_ = 0;
};

}  // namespace bench

namespace bench_nodes {

using Command = geometry_msgs::msg::TwistStamped;

// The yaw about z, the formula from the rotations topic. bench_core knows no ROS types, so the
// conversion from a message lives here.
[[nodiscard]] double yaw_of(const geometry_msgs::msg::Quaternion& q) {
  return std::atan2(2 * (q.w * q.z + q.x * q.y), 1 - 2 * (q.y * q.y + q.z * q.z));
}

// Drives the scenario's route: /odom is its feedback, /cmd_vel_nav its output. Every rule is in
// bench::Route; this node converts messages and holds the clock.
class RouteFollower : public rclcpp::Node {
 public:
  explicit RouteFollower(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
      : Node("route_follower", options),
        start_after_(std::chrono::milliseconds(declare_parameter<std::int64_t>("start_after_ms", 2000))),
        route_(declare_route()) {
    const rclcpp::QoS qos(rclcpp::KeepLast(10));
    commands_ = create_publisher<Command>("cmd_vel_nav", qos);
    odometry_ = create_subscription<nav_msgs::msg::Odometry>(
        "odom", qos, [this](const nav_msgs::msg::Odometry& message) { on_odometry(message); });
  }

 private:
  [[nodiscard]] bench::Route declare_route() {
    const auto x_m = declare_parameter<std::vector<double>>("goals_x", std::vector<double>{});
    const auto y_m = declare_parameter<std::vector<double>>("goals_y", std::vector<double>{});
    const double tolerance_m = declare_parameter<double>("tolerance_m", 0.10);
    const bench::Limits limits{.speed_mps = declare_parameter<double>("speed_mps", 0.20),
                               .turn_rps = declare_parameter<double>("turn_rps", 0.60),
                               .turn_first_rad = declare_parameter<double>("turn_first_rad", 0.20),
                               .turn_gain_hz = declare_parameter<double>("turn_gain_hz", 1.5)};
    if (x_m.size() != y_m.size()) throw std::runtime_error("goals_x and goals_y have different lengths");
    return {bench::goals_from(x_m, y_m, tolerance_m).value_or(std::vector<bench::Goal>{}), limits};
  }

  void on_odometry(const nav_msgs::msg::Odometry& message) {
    const rclcpp::Time stamp(message.header.stamp);
    if (!first_) {
      first_ = stamp;
      return;
    }
    if (std::chrono::nanoseconds((stamp - *first_).nanoseconds()) < start_after_) return;

    const bench::Pose pose{.x_m = message.pose.pose.position.x,
                           .y_m = message.pose.pose.position.y,
                           .yaw_rad = yaw_of(message.pose.pose.orientation)};
    const bench::Drive drive = route_.on_pose(pose);
    if (route_.done()) {
      if (!announced_) {
        announced_ = true;
        RCLCPP_INFO(get_logger(), "route done: %" PRId64 " goals reached", route_.reached());
      }
      return;
    }
    Command command;
    command.header.stamp = stamp;
    command.header.frame_id = "base_link";
    command.twist.linear.x = drive.forward_mps;
    command.twist.angular.z = drive.turn_rps;
    commands_->publish(command);
  }

  std::chrono::nanoseconds start_after_;
  bench::Route route_;
  std::optional<rclcpp::Time> first_;
  bool announced_ = false;
  rclcpp::Publisher<Command>::SharedPtr commands_;
  rclcpp::Subscription<nav_msgs::msg::Odometry>::SharedPtr odometry_;
};

}  // namespace bench_nodes

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<bench_nodes::RouteFollower>());
  rclcpp::shutdown();
}

// In the fixture: a fake that holds the robot at the origin facing along x.
nav_msgs::msg::Odometry at_origin() {
  nav_msgs::msg::Odometry message;
  message.header.stamp = fake->now();
  message.pose.pose.orientation.w = 1.0;  // the identity rotation, not a zero quaternion
  return message;
}

TEST_F(RouteFollowerTest, DrivesTowardsAGoalStraightAhead) {
  // start_after_ms is 0 here: without /clock the node's clock is the wall clock.
  ASSERT_TRUE(spin_until([&] { return !commands.empty(); }));
  EXPECT_DOUBLE_EQ(commands.front().twist.linear.x, 0.2);
  EXPECT_NEAR(commands.front().twist.angular.z, 0.0, 1e-9);
}

#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <compare>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <ranges>
#include <span>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

namespace bench {

// From bench/time.hpp, bench/drive.hpp and bench/scenario.hpp, as the earlier topics left them.
struct Time {
  std::chrono::nanoseconds since_epoch;
  auto operator<=>(const Time&) const = default;
};

struct Goal {
  double x_m = 0.0;
  double y_m = 0.0;
  double tolerance_m = 0.10;
};

struct Sample {
  Time at;
  double x_m = 0.0;
  double y_m = 0.0;
  double speed_mps = 0.0;
};

enum class Compare { at_least, at_most };

struct Check {
  std::string what;
  std::string unit;
  Compare compare;
  double limit;
  std::optional<double> measured;
};

[[nodiscard]] bool met(const Check& check) {
  if (!check.measured) return false;
  return check.compare == Compare::at_least ? *check.measured >= check.limit : *check.measured <= check.limit;
}

struct Verdict {
  std::string scenario;
  std::int64_t samples;
  bool passed;
  std::vector<Check> checks;
};

[[nodiscard]] Verdict judge(std::string scenario, std::int64_t samples, std::vector<Check> checks) {
  const bool passed = std::ranges::all_of(checks, met);
  return {.scenario = std::move(scenario), .samples = samples, .passed = passed, .checks = std::move(checks)};
}

namespace {

[[nodiscard]] double seconds(std::chrono::nanoseconds d) { return std::chrono::duration<double>(d).count(); }

[[nodiscard]] std::string with_unit(double value, std::string_view unit) {
  return unit.empty() ? std::format("{:.2f}", value) : std::format("{:.2f} {}", value, unit);
}

[[nodiscard]] std::string line(const Check& check) {
  const std::string measured = check.measured ? with_unit(*check.measured, check.unit) : std::string("not measured");
  return std::format("{:<6} {}: {}, {} {}\n", met(check) ? "ok" : "failed", check.what, measured,
                     check.compare == Compare::at_least ? "at least" : "at most", with_unit(check.limit, check.unit));
}

}  // namespace

[[nodiscard]] std::string describe(const Verdict& verdict) {
  std::string text = std::format("{}\nscenario: {}\nsamples: {}\n", verdict.passed ? "pass" : "fail",
                                 verdict.scenario, verdict.samples);
  for (const Check& check : verdict.checks) text += line(check);
  return text;
}

[[nodiscard]] std::optional<double> top_speed_mps(std::span<const Sample> run) {
  if (run.empty()) return std::nullopt;
  return std::ranges::max(run | std::views::transform([](const Sample& s) { return std::abs(s.speed_mps); }));
}

// New in this topic.

[[nodiscard]] double range_m(const Sample& sample, const Goal& goal) {
  return std::hypot(goal.x_m - sample.x_m, goal.y_m - sample.y_m);
}

// The samples at or after `from`. The run is in time order, so this is one binary search.
[[nodiscard]] std::span<const Sample> since(std::span<const Sample> run, Time from) {
  return {std::ranges::lower_bound(run, from, {}, &Sample::at), run.end()};
}

[[nodiscard]] std::optional<Time> reached_at(std::span<const Sample> run, const Goal& goal) {
  const auto inside =
      std::ranges::find_if(run, [&goal](const Sample& s) { return range_m(s, goal) <= goal.tolerance_m; });
  if (inside == run.end()) return std::nullopt;
  return inside->at;
}

[[nodiscard]] std::optional<Time> first_moved(std::span<const Sample> run, double speed_limit_mps) {
  const auto moving = std::ranges::find_if(
      run, [speed_limit_mps](const Sample& s) { return std::abs(s.speed_mps) > speed_limit_mps; });
  if (moving == run.end()) return std::nullopt;
  return moving->at;
}

// When each goal was reached, in order. It stops at the first goal the robot never reached, so a
// robot that passed goal 2 before goal 1 gets no credit for it.
[[nodiscard]] std::vector<Time> goal_times(std::span<const Sample> run, std::span<const Goal> goals) {
  std::vector<Time> times;
  std::span<const Sample> rest = run;
  for (const Goal& goal : goals) {
    const std::optional<Time> at = reached_at(rest, goal);
    if (!at) break;
    times.push_back(*at);
    rest = since(rest, *at);
  }
  return times;
}

// What normal operation requires: every goal in order, a stop near the last one, inside the time
// tolerance measured from the robot's first movement, and no speed above the limit.
[[nodiscard]] std::vector<Check> normal_checks(std::span<const Sample> run, std::span<const Goal> goals,
                                               std::chrono::nanoseconds time_limit, double speed_limit_mps) {
  const std::vector<Time> times = goal_times(run, goals);
  const std::optional<Time> moved = first_moved(run, 0.05);
  const auto took = [&]() -> std::optional<double> {
    if (times.size() != goals.size() || !moved) return std::nullopt;
    return seconds(times.back().since_epoch - moved->since_epoch);
  };
  const auto stopped_near = [&]() -> std::optional<double> {
    if (run.empty() || goals.empty()) return std::nullopt;
    return range_m(run.back(), goals.back());
  };
  return {{.what = "goals reached in order",
           .unit = "",
           .compare = Compare::at_least,
           .limit = static_cast<double>(std::ssize(goals)),
           .measured = static_cast<double>(std::ssize(times))},
          {.what = "distance from the last goal at the end",
           .unit = "m",
           .compare = Compare::at_most,
           .limit = goals.empty() ? 0.0 : goals.back().tolerance_m,
           .measured = stopped_near()},
          {.what = "time from the first movement to the last goal",
           .unit = "s",
           .compare = Compare::at_most,
           .limit = seconds(time_limit),
           .measured = took()},
          {.what = "top speed",
           .unit = "m/s",
           .compare = Compare::at_most,
           .limit = speed_limit_mps,
           .measured = top_speed_mps(run)}};
}

}  // namespace bench

// One odometry message of a made-up run, one second of simulated time apart.
struct Moment {
  std::chrono::seconds t;
  double x_m;
  double y_m;
  double speed_mps;
};

[[nodiscard]] std::vector<bench::Sample> samples(std::span<const Moment> moments) {
  std::vector<bench::Sample> run;
  for (const Moment& moment : moments) {
    run.push_back({.at = {moment.t}, .x_m = moment.x_m, .y_m = moment.y_m, .speed_mps = moment.speed_mps});
  }
  return run;
}

int main() {
  using namespace std::chrono_literals;
  constexpr std::array<bench::Goal, 2> goals{{{.x_m = 0.80, .y_m = 0.00, .tolerance_m = 0.10},
                                              {.x_m = 0.80, .y_m = 0.50, .tolerance_m = 0.10}}};

  // The route as it goes: the follower starts at 2 s, reaches the first goal, turns, and stops
  // inside the second one.
  constexpr std::array<Moment, 13> good{{{.t = 0s, .x_m = 0.00, .y_m = 0.00, .speed_mps = 0.00},
                                         {.t = 1s, .x_m = 0.00, .y_m = 0.00, .speed_mps = 0.00},
                                         {.t = 2s, .x_m = 0.00, .y_m = 0.00, .speed_mps = 0.00},
                                         {.t = 3s, .x_m = 0.20, .y_m = 0.00, .speed_mps = 0.20},
                                         {.t = 4s, .x_m = 0.40, .y_m = 0.00, .speed_mps = 0.20},
                                         {.t = 5s, .x_m = 0.60, .y_m = 0.00, .speed_mps = 0.20},
                                         {.t = 6s, .x_m = 0.72, .y_m = 0.00, .speed_mps = 0.00},
                                         {.t = 7s, .x_m = 0.72, .y_m = 0.02, .speed_mps = 0.00},
                                         {.t = 8s, .x_m = 0.75, .y_m = 0.20, .speed_mps = 0.20},
                                         {.t = 9s, .x_m = 0.78, .y_m = 0.40, .speed_mps = 0.20},
                                         {.t = 10s, .x_m = 0.79, .y_m = 0.45, .speed_mps = 0.05},
                                         {.t = 11s, .x_m = 0.79, .y_m = 0.45, .speed_mps = 0.00},
                                         {.t = 12s, .x_m = 0.79, .y_m = 0.45, .speed_mps = 0.00}}};
  const auto run = samples(good);
  std::cout << bench::describe(
      bench::judge("normal", std::ssize(run), bench::normal_checks(run, goals, 20s, 0.30)));
  std::cout << '\n';

  // The same run with the follower stalled after the first goal.
  std::array<Moment, 13> stalled = good;
  for (std::size_t i = 7; i < stalled.size(); ++i) {
    stalled[i] = {.t = stalled[i].t, .x_m = 0.72, .y_m = 0.00, .speed_mps = 0.00};
  }
  const auto stuck = samples(stalled);
  std::cout << bench::describe(
      bench::judge("normal", std::ssize(stuck), bench::normal_checks(stuck, goals, 20s, 0.30)));
}

// In on_tick(), the drive phase. For every other scenario the follower drives.
if (phase == bench::Phase::drive && scenario_ == "smoke") {
  Command command;
  command.header.stamp = now();
  command.header.frame_id = "base_link";
  command.twist.linear.x = speed_mps_;
  commands_->publish(command);
  last_command_ = now_time;
} else if (phase == bench::Phase::done) {
  finish();
}

// In finish(), in place of the single call to smoke_checks:
std::vector<bench::Check> checks =
    scenario_ == "smoke" ? bench::smoke_checks(plan_, elapsed, run_, last_command_.value_or(bench::Time{}))
                         : bench::normal_checks(run_, goals_, time_limit_, speed_limit_mps_);
verdict_ = bench::judge(scenario_, std::ssize(run_), std::move(checks));

// New members, read from the scenario's parameter file, and the helper that builds them:
[[nodiscard]] std::vector<bench::Goal> declare_goals() {
  const auto x_m = declare_parameter<std::vector<double>>("goals_x", std::vector<double>{});
  const auto y_m = declare_parameter<std::vector<double>>("goals_y", std::vector<double>{});
  if (x_m.size() != y_m.size()) throw std::runtime_error("goals_x and goals_y have different lengths");
  return bench::goals_from(x_m, y_m, declare_parameter<double>("tolerance_m", 0.10))
      .value_or(std::vector<bench::Goal>{});
}
std::vector<bench::Goal> goals_;
std::chrono::nanoseconds time_limit_;
double speed_limit_mps_;
